// Hand-authored geometric samples, NOT a child-handwriting accuracy dataset.
const kana={
  'く':[[[75,5],[25,48],[75,95]]],
  'し':[[[30,5],[28,35],[26,65],[30,85],[45,94],[62,90],[85,70]]],
  'り':[[[25,5],[22,30],[23,53],[30,45]],[[72,3],[75,40],[70,70],[58,88],[43,98]]],
  'き':[[[15,27],[80,20]],[[12,49],[87,41]],[[42,3],[50,35],[65,66]],[[27,68],[22,80],[40,93],[75,94]]],
  'や':[[[5,40],[40,22],[67,20],[83,29],[80,44],[62,52]],[[25,10],[42,95]],[[52,3],[61,15]]],
  'つ':[[[6,25],[30,17],[60,17],[81,25],[88,40],[84,57],[68,74],[40,86]]],
  'て':[[[8,20],[90,13],[66,30],[47,51],[43,72],[55,87],[78,94]]],
  'ん':[[[47,5],[27,46],[10,88],[29,60],[43,50],[53,55],[53,75],[60,90],[76,87],[94,65]]],
  'こ':[[[20,20],[72,19],[65,26]],[[23,63],[17,78],[31,89],[76,87]]],
  '゛':[[[76,2],[85,14]],[[93,0],[101,12]]]
};
function sample(text){
  const strokes=[];let x=12;
  for(const ch of text){
    const base=({'ゃ':'や','っ':'つ','ご':'こ'})[ch]||ch,scale='ゃっ'.includes(ch)?.58:1;
    const paths=[...kana[base],...(ch==='ご'?kana['゛']:[])];
    for(const pts of paths)strokes.push({lineWidth:4,points:pts.map(([px,py])=>({x:x+px*scale,y:8+py*scale+(scale<1?38:0)}))});
    x+=110*scale;
  }
  return strokes;
}
module.exports={sample,words:['くし','しし','くり','りんご','きゃく','きって']};
